"""DynamoDB access helpers for the PDF/Mail consumer."""

from typing import Any, Dict

import boto3
from botocore.exceptions import ClientError


class DynamoDBRepository:
    """Loads report items from DynamoDB."""

    def __init__(self, table_name: str, region: str = "us-east-1"):
        self.table_name = table_name
        self.table = boto3.resource("dynamodb", region_name=region).Table(table_name)

    def get_report(self, execution_id: str) -> Dict[str, Any]:
        try:
            response = self.table.get_item(Key={"PK": execution_id, "SK": "REPORT"})
        except ClientError as exc:
            raise RuntimeError(f"Failed to load report from DynamoDB: {exc}") from exc

        item = response.get("Item")
        if not item:
            raise ValueError(f"Report not found for execution_id: {execution_id}")

        return item

def lambda_handler(event: Any, context: Any) -> Dict[str, Any]:
    records: List[Dict[str, Any]] = (
        event.get("Records", []) if isinstance(event, dict) else []
    )

    if not records and isinstance(event, dict):
        logger.info(
            "pdf-mail-consumer invoked without SQS records", extra={"event": event}
        )
        return {"status": "NO_RECORDS", "processed_records": 0}

    try:
        orchestrator = PdfMailConsumerOrchestrator()
        result = orchestrator.process_records(records)
        processed = result.get("processed_records")
        recipients = result.get("recipients") or []
        success = result.get("status") == "SUCCESS"
        logger.info(
            "pdf-mail-consumer finished",
            extra={
                "processed_records": processed,
                "recipients": recipients,
                "success": success,
            },
        )
        return result

except Exception:
        logger.exception("Unexpected error in pdf-mail-consumer handler")
        raise

