        stroke_r, stroke_g, stroke_b = fill
    else:
        stroke_r, stroke_g, stroke_b = stroke

    return (
        "q\n"
        f"{fill_r:.3f} {fill_g:.3f} {fill_b:.3f} rg\n"
        f"{stroke_r:.3f} {stroke_g:.3f} {stroke_b:.3f} RG\n"
        f"{x:.2f} {y:.2f} {width:.2f} {height:.2f} re\n"
        "B\n"
        "Q"
    )


